<!-- This file is generated by AI. -->

<!--
  配音缓存与引用管理。

  缓存音频只由内容哈希寻址; 「移除」只清 `-vocal=`, 从不删文件。因此这里是**唯一**会删除
  音频的地方, 删除前先扫描项目中真实的 `-vocal=` 引用, 把"未被任何场景引用"的文件列给
  用户确认后再删。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { onMount } from 'svelte';
  import { SvelteSet } from 'svelte/reactivity';

  import { voiceScanReferences, type VocalReference } from '../commands/voice';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { errorSummary } from '../voice/errorText';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Checkbox from './Checkbox.svelte';
  import Spinner from './Spinner.svelte';

  let { onClose }: { onClose: () => void } = $props();

  /** 缓存列表来自 store (由控制器同步) */
  const tick = $derived(appStore.voiceTick);
  const cache = $derived.by(() => {
    // 必须落在这一层: `$derived` 用 `===` 比较结果, 只读 `voiceTick` 的浅派生会被它吞掉
    void tick;
    return appStore.voiceCache;
  });
  const projectPath = $derived(appStore.projectPath);

  /** 项目中真实的 `-vocal=` 引用; null 表示还没扫过 */
  let references = $state<VocalReference[] | null>(null);
  /** 选中的缓存哈希 (SvelteSet 自带响应式, 不需要 $state 包裹) */
  const selected = new SvelteSet<string>();
  let busy = $state(false);
  let error = $state<string | null>(null);
  let message = $state<string | null>(null);

  onMount(() => {
    // 缓存列表由控制器同步进 store; 打开面板时先补一次, 再扫项目引用
    void voiceController.refreshCache();
    void rescan();
  });

  async function rescan(): Promise<void> {
    const path = projectPath;
    if (!path) {
      references = [];
      return;
    }
    busy = true;
    error = null;
    try {
      references = await voiceScanReferences(path);
    } catch (caught) {
      error = errorSummary(String(caught));
    } finally {
      busy = false;
    }
  }

  /** 项目中被引用的音频绝对路径集合 */
  const referencedPaths = $derived.by(() => {
    const set = new SvelteSet<string>();
    for (const reference of references ?? []) set.add(normalize(reference.path));
    return set;
  });

  const orphans = $derived(cache.filter((entry) => !referencedPaths.has(normalize(entry.path))));
  const missing = $derived((references ?? []).filter((reference) => !reference.exists));

  function toggle(hash: string): void {
    if (selected.has(hash)) selected.delete(hash);
    else selected.add(hash);
  }

  async function purge(): Promise<void> {
    const count = selected.size;
    if (count === 0) return;
    busy = true;
    try {
      await voiceController.clearCache([...selected]);
      selected.clear();
      message = `已删除 ${count} 个缓存文件`;
      await rescan();
    } catch (caught) {
      error = errorSummary(String(caught));
    } finally {
      busy = false;
    }
  }

  const totalSize = $derived(cache.reduce((sum, entry) => sum + entry.size, 0));
  const orphanSize = $derived(orphans.reduce((sum, entry) => sum + entry.size, 0));

  /** 路径归一化: 大小写与分隔符在 Windows 下不敏感 */
  function normalize(path: string): string {
    return path.replace(/\//g, '\\').toLowerCase();
  }

  function formatSize(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
    return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
  }
</script>

<AppDialog
  title="配音缓存与引用"
  description="缓存音频只由内容哈希寻址；删除缓存只影响历史记录的试听，已应用的音频位于项目内，不受影响。"
  size="large"
  height={600}
  compact
  {onClose}
>
  <div class="dialog-toolbar">
    <Button appearance="bare" icon="ArrowSync" title="重新扫描项目引用" onclick={() => void rescan()}>
      重新扫描项目引用
    </Button>
    {#if busy}
      <Spinner size={12} />
    {/if}
    <span class="dialog-toolbar-grow"></span>
    <Button
      disabled={orphans.length === 0}
      onclick={() => {
        selected.clear();
        for (const entry of orphans) selected.add(entry.hash);
      }}
    >
      全选未引用
    </Button>
    <Button appearance="primary" icon="Delete" disabled={selected.size === 0} onclick={() => void purge()}>
      删除选中（{selected.size}）
    </Button>
  </div>

  <p class="voice-dialog-hint">
    缓存共 {cache.length} 个文件（{formatSize(totalSize)}），其中未被任何场景引用 {orphans.length} 个（
    {formatSize(orphanSize)}）。
  </p>

  {#if error}
    <p class="voice-error">{error}</p>
  {/if}
  {#if message}
    <p class="voice-dialog-hint">{message}</p>
  {/if}

  {#if missing.length > 0}
    <div class="voice-warn-block">
      <strong>脚本引用了 {missing.length} 个不存在的音频文件：</strong>
      {#each missing.slice(0, 20) as reference (`${reference.scene}:${reference.line}`)}
        <div class="voice-warn-line">{reference.scene}:{reference.line + 1} → {reference.vocal}</div>
      {/each}
    </div>
  {/if}

  <div class="cache-list dialog-scroll">
    {#if cache.length === 0}
      <p class="voice-dialog-empty">缓存为空。</p>
    {/if}
    {#each cache as entry (entry.hash)}
      <div class="cache-item" class:orphan={!referencedPaths.has(normalize(entry.path))}>
        <Checkbox checked={selected.has(entry.hash)} onchange={() => toggle(entry.hash)} />
        <span class="cache-hash">{entry.hash}</span>
        <span class="cache-size">{formatSize(entry.size)}</span>
        <span class="cache-flag">{referencedPaths.has(normalize(entry.path)) ? '已引用' : '未被引用'}</span>
      </div>
    {/each}
  </div>

  {#snippet footer()}
    <Button onclick={onClose}>关闭</Button>
  {/snippet}
</AppDialog>
